package vista.controlador;
import java.util.*;import javafx.application.Platform;import javafx.collections.*;import javafx.concurrent.Task;import javafx.fxml.FXML;import javafx.scene.control.*;import javafx.beans.property.SimpleStringProperty;import servicio.RankingDeportivoService;import servicio.RankingDeportivoService.*;import vista.Navegacion;
public class RankingsController {private final RankingDeportivoService service=new RankingDeportivoService();private final ObservableList<Posicion> filas=FXCollections.observableArrayList();private final ObservableList<Aporte> aportes=FXCollections.observableArrayList();@FXML private ComboBox<Categoria> filtroCategoria;@FXML private TableView<Posicion> tablaRanking;@FXML private TableColumn<Posicion,String> colPos,colJugador,colPuntos,colPJ,colPG,colEfectividad,colSets,colGames;@FXML private TableView<Aporte> tablaAuditoria;@FXML private TableColumn<Aporte,String> colFecha,colTorneo,colFase,colResultado,colBase,colBonus,colTotal;@FXML private Label etiquetaEstado,etiquetaCategoria,etiquetaParticipantes,etiquetaPartidos;
 @FXML private void initialize(){tablaRanking.setItems(filas);tablaAuditoria.setItems(aportes);colPos.setCellValueFactory(x->p(x.getValue().posicion()));colJugador.setCellValueFactory(x->p(x.getValue().jugador()));colPuntos.setCellValueFactory(x->p(x.getValue().puntos()));colPJ.setCellValueFactory(x->p(x.getValue().partidos()));colPG.setCellValueFactory(x->p(x.getValue().victorias()));colEfectividad.setCellValueFactory(x->p(x.getValue().efectividad()+"%"));colSets.setCellValueFactory(x->p(x.getValue().diferenciaSets()));colGames.setCellValueFactory(x->p(x.getValue().diferenciaGames()));colFecha.setCellValueFactory(x->p(x.getValue().fecha().toLocalDate().toString()));colTorneo.setCellValueFactory(x->p(x.getValue().torneo()+" · "+x.getValue().categoria()));colFase.setCellValueFactory(x->p(x.getValue().fase()));colResultado.setCellValueFactory(x->p(x.getValue().resultado()));colBase.setCellValueFactory(x->p(x.getValue().base()));colBonus.setCellValueFactory(x->p(x.getValue().bonus()));colTotal.setCellValueFactory(x->p(x.getValue().total()));filtroCategoria.valueProperty().addListener((o,a,n)->{if(n!=null)cargarRanking();});tablaRanking.getSelectionModel().selectedItemProperty().addListener((o,a,n)->cargarAuditoria(n));cargarCategorias();}
 private SimpleStringProperty p(Object x){return new SimpleStringProperty(String.valueOf(x));}
 private void cargarCategorias(){tarea(()->service.categorias(),x->{filtroCategoria.getItems().setAll(x);if(!x.isEmpty())filtroCategoria.setValue(x.get(Math.min(4,x.size()-1)));},"categorias");}
 @FXML private void cargarRanking(){Categoria c=filtroCategoria.getValue();if(c==null)return;etiquetaEstado.setText("Calculando ranking...");tarea(()->service.calcular(c.id()),x->{filas.setAll(x);aportes.clear();etiquetaCategoria.setText(c.nombre());etiquetaParticipantes.setText(x.size()+" jugadores");etiquetaPartidos.setText(x.stream().mapToInt(Posicion::partidos).sum()/2+" partidos auditados");etiquetaEstado.setText(x.isEmpty()?"Todavia no hay resultados para esta categoria.":"Ranking reconstruido desde resultados oficiales.");if(!x.isEmpty())tablaRanking.getSelectionModel().selectFirst();},"ranking");}
 private void cargarAuditoria(Posicion p){if(p==null){aportes.clear();return;}Categoria c=filtroCategoria.getValue();tarea(()->service.auditar(p.perfilId(),c.id()),aportes::setAll,"auditoria");}
 private <T> void tarea(java.util.concurrent.Callable<T> c,java.util.function.Consumer<T> ok,String nombre){Task<T> t=new Task<>(){protected T call()throws Exception{return c.call();}};t.setOnSucceeded(e->ok.accept(t.getValue()));t.setOnFailed(e->{etiquetaEstado.setText("No se pudo cargar "+nombre+".");t.getException().printStackTrace();});Thread h=new Thread(t,"rankings-"+nombre);h.setDaemon(true);h.start();}
 @FXML private void volver(){Navegacion.mostrarDashboard(Navegacion.getUsuarioActual());}
}
